package com.obysoft.faithOS.controller;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.obysoft.faithOS.dto.*;import com.obysoft.faithOS.service.AttendanceDeviceService;import jakarta.validation.Valid;@RestController@RequestMapping("/api/attendance-devices")@PreAuthorize("hasAnyRole('SUPER_ADMIN','CHURCH_ADMIN')")public class AttendanceDeviceAdminController{private final AttendanceDeviceService service;public AttendanceDeviceAdminController(AttendanceDeviceService s){service=s;}@GetMapping public List<AttendanceDeviceResponse> all(){return service.all();}@PostMapping public ResponseEntity<AttendanceDeviceResponse> create(@Valid@RequestBody AttendanceDeviceRequest r){return ResponseEntity.status(201).body(service.create(r));}@PostMapping("/{id}/rotate")public AttendanceDeviceResponse rotate(@PathVariable Long id){return service.rotate(id);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void revoke(@PathVariable Long id){service.revoke(id);}}
